<?php require_once '../config/db.php'; require_once '../includes/auth.php'; require_role('admin');
$students=$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$faculty=$pdo->query("SELECT COUNT(*) FROM users WHERE role='faculty'")->fetchColumn();$subjects=$pdo->query("SELECT COUNT(*) FROM subjects")->fetchColumn();$materials=$pdo->query("SELECT COUNT(*) FROM materials")->fetchColumn();$downloads=$pdo->query("SELECT COUNT(*) FROM downloads")->fetchColumn();$papers=$pdo->query("SELECT COUNT(*) FROM materials WHERE material_type='question_paper'")->fetchColumn();$recent=$pdo->query("SELECT m.title,s.name subject_name,u.name uploader,m.uploaded_at FROM materials m JOIN subjects s ON s.id=m.subject_id JOIN users u ON u.id=m.uploaded_by ORDER BY m.id DESC LIMIT 5")->fetchAll();
