<?php foreach([['👤',$students,'Students'],['👥',$faculty,'Faculty'],['▤',$subjects,'Subjects'],['📄',$materials,'Materials'],['⇩',$downloads,'Downloads'],['▤',$papers,'Question Papers']] as $x):?><div class="stat"><div class="stat-icon"><?=$x[0]?></div><div><strong><?=$x[1]?></strong><span><?=$x[2]?></span></div></div><?php endforeach;?></div>
<div class="table-card recent"><h3>Recent Materials</h3><table><thead><tr><th>Title</th><th>Subject</th><th>Uploaded By</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['uploader'])?></td><td><?=date('d M Y',strtotime($r['uploaded_at']))?></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>